/** Request validation. Every problem is collected so the client sees all offending fields at once. */

export interface FieldError {
  field: string;
  message: string;
}

export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

export interface Parsed<T> {
  value?: T;
  errors: FieldError[];
}

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
export const MAX_BODY_BYTES = 1_048_576;

const isPlainObject = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);

function integerField(obj: Record<string, unknown>, name: string, min: number, max: number, fallback: number, errors: FieldError[]): number {
  if (!Object.hasOwn(obj, name)) return fallback;
  const v = obj[name];
  if (typeof v === 'number' && Number.isInteger(v) && v >= min && v <= max) return v;
  errors.push({ field: name, message: `${name} must be an integer from ${min} to ${max}.` });
  return fallback;
}

/** Validates the request body. `text` is the decoded body; `tooLarge` means it exceeded the limit. */
export function parseSubmission(contentType: string | undefined, text: string, tooLarge: boolean): Parsed<NewJob> {
  const mediaType = (contentType ?? '').split(';')[0]!.trim().toLowerCase();
  if (mediaType !== 'application/json') return { errors: [{ field: 'body', message: 'Content-Type must be application/json.' }] };
  if (tooLarge) return { errors: [{ field: 'body', message: `Request body must be at most ${MAX_BODY_BYTES} bytes.` }] };

  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch {
    return { errors: [{ field: 'body', message: 'Request body is not valid JSON.' }] };
  }
  if (!isPlainObject(parsed)) return { errors: [{ field: 'body', message: 'Request body must be a JSON object.' }] };

  const errors: FieldError[] = [];
  for (const key of Object.keys(parsed)) {
    if (!ALLOWED_FIELDS.has(key)) errors.push({ field: key, message: 'Unknown field.' });
  }

  let input = '';
  if (!Object.hasOwn(parsed, 'input')) {
    errors.push({ field: 'input', message: 'input is required.' });
  } else if (typeof parsed.input !== 'string') {
    errors.push({ field: 'input', message: 'input must be a string.' });
  } else if (parsed.input.length < 1 || parsed.input.length > 1000) {
    errors.push({ field: 'input', message: 'input must be 1 to 1000 characters.' });
  } else if (parsed.input.trim() === '') {
    errors.push({ field: 'input', message: 'input must not be blank.' });
  } else {
    input = parsed.input;
  }

  const steps = integerField(parsed, 'steps', 1, 20, 5, errors);
  const failAttempts = integerField(parsed, 'failAttempts', 0, 5, 0, errors);

  if (errors.length > 0) return { errors };
  return { value: { input, steps, failAttempts }, errors: [] };
}

/** Validates an optional Idempotency-Key header value. Node joins duplicate headers with ", ", which fails the pattern. */
export function parseIdempotencyKey(value: string | string[] | undefined): Parsed<string> {
  if (value === undefined) return { errors: [] };
  if (typeof value === 'string' && IDEMPOTENCY_KEY_RE.test(value)) return { value, errors: [] };
  return {
    errors: [{ field: 'Idempotency-Key', message: 'Idempotency-Key must match ^[A-Za-z0-9_-]{1,128}$.' }],
  };
}

