import { randomUUID } from 'node:crypto';
import type { DatabaseSync } from 'node:sqlite';
import { transaction } from './db.ts';
import type { NewJob } from './validation.ts';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** Public job representation returned by every endpoint that returns a job. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

/** Raw database row (snake_case columns). */
interface JobRow {
  seq: number;
  id: string;
  idempotency_key: string | null;
  input: string;
  steps: number;
  fail_attempts: number;
  status: JobStatus;
  attempts: number;
  completed_steps: number;
  output: string | null;
  error: string | null;
  created_at: string;
  updated_at: string;
  available_at: number;
}

export const MAX_ATTEMPTS = 3;
export const RETRY_DELAY_MS = 500;
export const TRANSIENT_FAILURE = 'transient failure';
/** The worker is considered up if its heartbeat is at most this old. */
export const HEARTBEAT_FRESH_MS = 3000;

export function serializeJob(r: JobRow): Job {
  return {
    id: r.id,
    status: r.status,
    input: r.input,
    steps: r.steps,
    failAttempts: r.fail_attempts,
    attempts: r.attempts,
    progress: { completed: r.completed_steps, total: r.steps },
    result: r.status === 'completed' ? { output: r.output ?? '' } : null,
    error: r.status === 'failed' ? r.error : null,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
  };
}

function rowById(db: DatabaseSync, id: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow | undefined;
}

export function getJob(db: DatabaseSync, id: string): Job | undefined {
  const r = rowById(db, id);
  return r && serializeJob(r);
}

export function listJobs(db: DatabaseSync): Job[] {
  const rows = db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
  return rows.map(serializeJob);
}

export type SubmitResult = { kind: 'created'; job: Job } | { kind: 'replayed'; job: Job } | { kind: 'conflict' };

/**
 * Creates a job, or handles an idempotent replay. The lookup and insert share one transaction, and
 * the UNIQUE constraint on idempotency_key is the final guard across processes and restarts.
 */
export function submitJob(db: DatabaseSync, payload: NewJob, key: string | undefined): SubmitResult {
  return transaction(db, (): SubmitResult => {
    if (key !== undefined) {
      const existing = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(key) as unknown as JobRow | undefined;
      if (existing) {
        const same =
          existing.input === payload.input && existing.steps === payload.steps && existing.fail_attempts === payload.failAttempts;
        return same ? { kind: 'replayed', job: serializeJob(existing) } : { kind: 'conflict' };
      }
    }
    const id = randomUUID();
    const now = new Date();
    const iso = now.toISOString();
    db.prepare(
      `INSERT INTO jobs (id, idempotency_key, input, steps, fail_attempts, status, attempts, completed_steps,
                         output, error, created_at, updated_at, available_at)
       VALUES (?, ?, ?, ?, ?, 'queued', 0, 0, NULL, NULL, ?, ?, ?)`,
    ).run(id, key ?? null, payload.input, payload.steps, payload.failAttempts, iso, iso, now.getTime());
    // Snapshot inside the transaction: once committed, the worker may already have claimed the job.
    return { kind: 'created', job: serializeJob(rowById(db, id)!) };
  });
}

export function writeHeartbeat(db: DatabaseSync, now: number): void {
  db.prepare(
    `INSERT INTO worker_heartbeat (id, beat_at) VALUES (1, ?)
     ON CONFLICT (id) DO UPDATE SET beat_at = excluded.beat_at`,
  ).run(now);
}

export function clearHeartbeat(db: DatabaseSync): void {
  db.prepare('DELETE FROM worker_heartbeat').run();
}

export function isWorkerUp(db: DatabaseSync, now: number): boolean {
  const r = db.prepare('SELECT beat_at FROM worker_heartbeat WHERE id = 1').get() as { beat_at: number } | undefined;
  return r !== undefined && now - r.beat_at <= HEARTBEAT_FRESH_MS;
}

/** What the worker needs to run an attempt. */
export interface Claim {
  id: string;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
}

/**
 * Returns the next job to run. An interrupted running job (left behind by a crashed worker) is
 * resumed first, keeping its attempt number. Otherwise the oldest eligible queued job starts a new attempt.
 */
export function claimNext(db: DatabaseSync, now: number): Claim | undefined {
  const iso = new Date(now).toISOString();
  return transaction(db, (): Claim | undefined => {
    let r = db.prepare("SELECT * FROM jobs WHERE status = 'running' ORDER BY seq LIMIT 1").get() as unknown as JobRow | undefined;
    if (r) {
      db.prepare('UPDATE jobs SET completed_steps = 0, updated_at = ? WHERE id = ?').run(iso, r.id);
    } else {
      r = db
        .prepare("SELECT * FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq LIMIT 1")
        .get(now) as unknown as JobRow | undefined;
      if (!r) return undefined;
      db.prepare(
        `UPDATE jobs SET status = 'running', attempts = attempts + 1, completed_steps = 0,
                         output = NULL, error = NULL, updated_at = ?
         WHERE id = ?`,
      ).run(iso, r.id);
      r = rowById(db, r.id)!;
    }
    return { id: r.id, input: r.input, steps: r.steps, failAttempts: r.fail_attempts, attempts: r.attempts };
  });
}

export function recordProgress(db: DatabaseSync, id: string, completed: number, now: number): void {
  db.prepare("UPDATE jobs SET completed_steps = ?, updated_at = ? WHERE id = ? AND status = 'running'").run(
    completed,
    new Date(now).toISOString(),
    id,
  );
}

export function completeJob(db: DatabaseSync, id: string, output: string, now: number): void {
  db.prepare(
    `UPDATE jobs SET status = 'completed', completed_steps = steps, output = ?, error = NULL, updated_at = ?
     WHERE id = ? AND status = 'running'`,
  ).run(output, new Date(now).toISOString(), id);
}

/** Returns a failed attempt to the queue, eligible again after RETRY_DELAY_MS. The deadline is persisted. */
export function scheduleRetry(db: DatabaseSync, id: string, now: number): void {
  db.prepare(
    `UPDATE jobs SET status = 'queued', completed_steps = 0, output = NULL, error = NULL,
                     available_at = ?, updated_at = ?
     WHERE id = ? AND status = 'running'`,
  ).run(now + RETRY_DELAY_MS, new Date(now).toISOString(), id);
}

export function failJob(db: DatabaseSync, id: string, now: number): void {
  db.prepare(
    `UPDATE jobs SET status = 'failed', completed_steps = 0, output = NULL, error = ?, updated_at = ?
     WHERE id = ? AND status = 'running'`,
  ).run(TRANSIENT_FAILURE, new Date(now).toISOString(), id);
}

