  const error: Record<string, unknown> = { code, message };
  if (fields) error.fields = fields;
  sendJson(res, status, { error });
}

function sendMethodNotAllowed(res: ServerResponse, allow: string[]): void {
  sendJson(res, 405, { error: { code: 'method_not_allowed', message: `Method not allowed. Allowed: ${allow.join(', ')}.` } }, {
    allow: allow.join(', '),
  });
}

function readBody(req: IncomingMessage): Promise<{ text: string; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve({ text: Buffer.concat(chunks).toString('utf8'), tooLarge }));
    req.on('error', reject);
  });
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  // Read the body before deciding anything, so every validation problem can be reported together.
  const { text, tooLarge } = await readBody(req);
  const body = parseSubmission(req.headers['content-type'], text, tooLarge);
  const key = parseIdempotencyKey(req.headers['idempotency-key']);
  const errors = [...body.errors, ...key.errors];
  if (errors.length > 0 || !body.value) {
    sendError(res, 400, 'invalid_request', 'The request is invalid.', errors);
    return;
  }
  const result = submitJob(db, body.value, key.value);
  if (result.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    return;
  }
  sendJson(res, result.kind === 'created' ? 201 : 200, result.job);
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const path = new URL(req.url ?? '/', 'http://localhost').pathname;
  const method = req.method ?? 'GET';

  if (path === '/') {
    if (method !== 'GET') return sendMethodNotAllowed(res, ['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (path === '/health') {
    if (method !== 'GET') return sendMethodNotAllowed(res, ['GET']);
    sendJson(res, 200, { status: 'ok', worker: isWorkerUp(db, Date.now()) ? 'up' : 'down' });
    return;
  }

  if (path === '/api/jobs') {
    if (method === 'GET') return sendJson(res, 200, { jobs: listJobs(db) });
    if (method === 'POST') return handleCreate(req, res);
    return sendMethodNotAllowed(res, ['GET', 'POST']);
  }

  const match = /^\/api\/jobs\/([^/]+)$/.exec(path);
  if (match) {
    if (method !== 'GET') return sendMethodNotAllowed(res, ['GET']);
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      return sendError(res, 404, 'not_found', 'Job not found.');
    }
    const job = getJob(db, id);
    if (!job) return sendError(res, 404, 'not_found', 'Job not found.');
    return sendJson(res, 200, job);
  }

  sendError(res, 404, 'not_found', 'Not found.');
}

const server = createServer((req, res) => {
  handle(req, res).catch((error: unknown) => {
    console.error('request failed:', error);
    if (res.headersSent) {
      res.end();
    } else {
      sendError(res, 500, 'internal_error', 'An internal error occurred.');
    }
  });
});

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  // Stop accepting connections, let active requests finish briefly, then force the rest closed.
  server.close(() => {
    clearTimeout(force);
    db.close();
    process.exit(0);
  });
  server.closeIdleConnections();
  const force = setTimeout(() => server.closeAllConnections(), DRAIN_MS);
  force.unref();
}

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

const port = Number(process.env.PORT ?? 3000);
server.on('error', (error) => {
  console.error('server error:', error);
  process.exit(1);
});
server.listen(port, () => console.log(`server listening on ${port}`));

