import { setTimeout as sleep } from 'node:timers/promises';
import { initSchema, openDatabase } from './db.ts';
import {
  claimNext,
  clearHeartbeat,
  completeJob,
  failJob,
  MAX_ATTEMPTS,
  recordProgress,
  scheduleRetry,
  writeHeartbeat,
  type Claim,
} from './jobs.ts';
import type { DatabaseSync } from 'node:sqlite';

const STEP_MS = 100;
const POLL_MS = 100;
const HEARTBEAT_MS = 500;

const db: DatabaseSync = openDatabase();
initSchema(db);

let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

/**
 * Runs one attempt step by step. Each step's progress is committed on its own. Returns without
 * changing the row if stopping, so an interrupted attempt stays `running` and is resumed on restart.
 */
async function runAttempt(claim: Claim): Promise<void> {
  for (let step = 0; step < claim.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return;
    if (step === 0 && claim.attempts <= claim.failAttempts) {
      if (claim.attempts < MAX_ATTEMPTS) scheduleRetry(db, claim.id, Date.now());
      else failJob(db, claim.id, Date.now());
      return;
    }
    if (step === claim.steps - 1) completeJob(db, claim.id, claim.input.toUpperCase(), Date.now());
    else recordProgress(db, claim.id, step + 1, Date.now());
  }
}

const beat = (): void => writeHeartbeat(db, Date.now());
beat();
const heartbeatTimer = setInterval(beat, HEARTBEAT_MS);

console.log('worker started');
try {
  while (!stopping) {
    const claim = claimNext(db, Date.now());
    if (!claim) {
      await sleep(POLL_MS);
      continue;
    }
    await runAttempt(claim);
  }
} finally {
  clearInterval(heartbeatTimer);
  clearHeartbeat(db);
  db.close();
  console.log('worker stopped');
}

